package dev.codewitness.core.evidence;

/**
 * The kind of experiment or analysis that produced a piece of evidence.
 *
 * <p>Deterministic types ({@code COMPILER} … {@code COUNTEREXAMPLE}) are produced by executing
 * tools. {@code LLM_ANALYSIS} is advisory and is never treated as proof of correctness.
 */
public enum EvidenceType {
    /** Project inspection: language, build system, modules. */
    PROJECT_INSPECTION,
    /** Compilation or build output. */
    COMPILER,
    /** Execution of the project's existing test suite. */
    TEST,
    /** Execution of tests generated by CodeWitness. */
    GENERATED_TEST,
    /** Execution of property based tests. */
    PROPERTY_TEST,
    /** Execution of randomised (fuzz) input sequences. */
    FUZZ_TEST,
    /** Static analysis findings. */
    STATIC_ANALYSIS,
    /** Coverage measurement. */
    COVERAGE,
    /** Mutation testing. */
    MUTATION_TEST,
    /** Security analysis. */
    SECURITY_SCAN,
    /** Dependency analysis. */
    DEPENDENCY_SCAN,
    /** Preparation of an ephemeral database the run's tests and scenarios can exercise. */
    DATABASE_FIXTURE,
    /** A concrete reproduction of a requirement violation. */
    COUNTEREXAMPLE,
    /** A structured interpretation of a natural language requirement. */
    REQUIREMENT_INTERPRETATION,
    /** Output of a language model. Advisory only. */
    LLM_ANALYSIS,
    /** Budget or infrastructure limit that stopped verification. */
    INFRASTRUCTURE,
    /** Recorded environment information for reproducibility. */
    ENVIRONMENT
}
